import React, { useState } from "react";
import { FaFire, FaStar, FaThumbsUp, FaCheck } from "react-icons/fa";

/**
 * Dynamic config per score tier:
 *  ≥ 85  → Top Match   (fire icon, deep green)
 *  ≥ 70  → Great Match (star icon, moss green — project primary)
 *  ≥ 50  → Good Match  (thumbs-up icon, amber — project secondary)
 *  < 50  → Fair Match  (star icon, slate)
 */
const getTierConfig = (score) => {
    if (score >= 85) return {
        label: "Top Match",
        Icon: FaFire,
        badgeBg: "bg-green-900",
        badgeText: "text-white",
        barColor: "bg-green-700",
        headerColor: "text-green-900",
    };
    if (score >= 50) return {
        label: "Good Match",
        Icon: FaThumbsUp,
        badgeBg: "bg-amber-500",
        badgeText: "text-white",
        barColor: "bg-amber-400",
        headerColor: "text-amber-600",
    };
    return {
        label: "Fair Match",
        Icon: FaStar,
        badgeBg: "bg-slate-500",
        badgeText: "text-white",
        barColor: "bg-slate-400",
        headerColor: "text-slate-600",
    };
};

const RecommendationBadge = ({ score, reasons, className = "" }) => {
    const [showTooltip, setShowTooltip] = useState(false);

    if (score == null) return null;

    const config = getTierConfig(score);
    const { label, Icon, badgeBg, badgeText, barColor, headerColor } = config;
    const displayReasons = reasons?.slice(0, 4) || [];

    return (
        <div
            className={`absolute z-10 ${className}`}
            onMouseEnter={() => setShowTooltip(true)}
            onMouseLeave={() => setShowTooltip(false)}
        >
            {/* ── Pill Badge ── */}
            <div
                className={`flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold shadow-md cursor-default select-none ${badgeBg} ${badgeText}`}
            >
                <Icon className="w-2.5 h-2.5 flex-shrink-0" />
                <span>{score}% · {label}</span>
            </div>

            {/* ── Tooltip ── */}
            {showTooltip && (
                <div className="absolute top-full right-0 mt-1.5 w-60 bg-white rounded-xl shadow-2xl border border-gray-100 p-3 z-20">

                    {/* Header */}
                    <div className="flex items-center justify-between mb-2">
                        <div className={`flex items-center gap-1.5 font-bold text-xs ${headerColor}`}>
                            <Icon className="w-3 h-3" />
                            {label}
                        </div>
                        <span className={`text-xs font-extrabold ${headerColor}`}>{score}%</span>
                    </div>

                    {/* Score bar */}
                    <div className="w-full bg-gray-100 rounded-full h-1.5 mb-3">
                        <div
                            className={`h-1.5 rounded-full transition-all ${barColor}`}
                            style={{ width: `${score}%` }}
                        />
                    </div>

                    {/* Reasons */}
                    {displayReasons.length > 0 ? (
                        <>
                            <p className="text-[10px] font-semibold text-gray-500 uppercase tracking-wide mb-1.5">
                                Why it matches
                            </p>
                            <ul className="space-y-1">
                                {displayReasons.map((reason, i) => (
                                    <li
                                        key={i}
                                        className="text-xs text-gray-600 flex items-start gap-1.5"
                                    >
                                        <FaCheck className="w-2.5 h-2.5 text-green-500 mt-0.5 flex-shrink-0" />
                                        {reason}
                                    </li>
                                ))}
                            </ul>
                        </>
                    ) : (
                        <p className="text-xs text-gray-400 italic">
                            Based on your profile preferences.
                        </p>
                    )}
                </div>
            )}
        </div>
    );
};

export default RecommendationBadge;
