/**
 * Haversine distance between two lat/lng points (in km)
 */
/* ─── DISTANCE STRATEGY ──────────────────────────────────────────────────────
 * All distances start as haversine (straight-line) from the backend.
 * The frontend then upgrades them to Google Maps road distances via
 * applyRoadDistances() when the Maps SDK is available.
 * If the SDK is unavailable, displayDistance() applies a 1.3× fallback correction.
 * ─────────────────────────────────────────────────────────────────────────── */
export function haversineDistance(lat1, lng1, lat2, lng2) {
    const toRad = (deg) => (deg * Math.PI) / 180;
    const R = 6371; // Earth radius in km

    const dLat = toRad(lat2 - lat1);
    const dLng = toRad(lng2 - lng1);

    const a =
        Math.sin(dLat / 2) * Math.sin(dLat / 2) +
        Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) *
        Math.sin(dLng / 2) * Math.sin(dLng / 2);

    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
}

/**
 * Convert a raw distance value for display.
 * - If isExact (came from Google Distance Matrix): return as-is, no ~
 * - If haversine (SDK unavailable fallback): apply 1.3× road correction
 * @param {number} km - raw distance value
 * @param {boolean} isExact - true = skip correction (already a road distance)
 * @returns {number | null}
 */
export function displayDistance(km, isExact = false) {
    if (km == null) return null;
    if (isExact) return Math.round(km * 10) / 10;
    return Math.round(km * 1.3 * 10) / 10;
}

/**
 * Get user's current location via browser geolocation API
 * Falls back to IP-based geolocation if browser geolocation fails
 * Returns { lat, lng } or rejects with descriptive error
 */
export function getUserLocation() {
    return new Promise((resolve, reject) => {
        if (!navigator.geolocation) {
            getLocationByIP().then(resolve).catch(reject);
            return;
        }

        navigator.geolocation.getCurrentPosition(
            (position) => {
                resolve({
                    lat: position.coords.latitude,
                    lng: position.coords.longitude,
                });
            },
            (error) => {
                if (error.code === error.PERMISSION_DENIED) {
                    reject(new Error('Could not get your location. Please try again.'));
                } else {
                    getLocationByIP().then(resolve).catch(reject);
                }
            }
        );
    });
}

// TODO: Add a privacy notice / consent mechanism before calling this third-party service.
// This function uses ipapi.co (https://ipapi.co) to determine location by IP address.
// Users should be informed that their IP address will be sent to a third-party service.
async function getLocationByIP() {
    try {
        const response = await fetch('https://ipapi.co/json/');
        const data = await response.json();
        if (data.latitude && data.longitude) {
            return { lat: data.latitude, lng: data.longitude };
        }
    } catch (e) {
        // Fallback to default demo coordinates (Nagpur campus area)
    }
    return { lat: 21.1458, lng: 79.0882 };
}

function extractCoords(item) {
    let lat =
        item.location?.lat ??
        item.lat ??
        item.latitude ??
        null;
    let lng =
        item.location?.lng ??
        item.location?.long ??
        item.lng ??
        item.longitude ??
        null;

    return {
        lat: lat ? Number(lat) : null,
        lng: lng ? Number(lng) : null
    };
}

/**
 * Upgrade haversine distances to actual Google Maps road distances.
 * Used for both Near Me results and Recommendations.
 * Falls back to haversine × 1.3 if the Maps SDK is unavailable.
 */
export async function applyRoadDistances(items, originLat, originLng) {
    if (!originLat || !originLng || !items || items.length === 0) {
        return items;
    }

    const oLat = Number(originLat);
    const oLng = Number(originLng);

    const applyHaversineFallback = (collection) => {
        return collection.map(item => {
            const { lat, lng } = extractCoords(item);
            if (lat && lng) {
                return {
                    ...item,
                    // Preserve existing backend distance if available, otherwise compute
                    distance: item.distance ?? haversineDistance(oLat, oLng, lat, lng),
                    distanceIsExact: false
                };
            }
            return item;
        });
    };

    if (!window.google || !window.google.maps || !window.google.maps.DistanceMatrixService) {
        return applyHaversineFallback(items);
    }

    const destinations = items
        .map(item => extractCoords(item))
        .filter(loc => loc.lat && loc.lng)
        .slice(0, 25);

    if (destinations.length === 0) {
        return items;
    }

    try {
        const service = new window.google.maps.DistanceMatrixService();
        const response = await service.getDistanceMatrix({
            origins: [{ lat: oLat, lng: oLng }],
            destinations: destinations,
            travelMode: window.google.maps.TravelMode.DRIVING,
        });

        if (response && response.rows && response.rows[0] && response.rows[0].elements) {
            const elements = response.rows[0].elements;
            let destIndex = 0;

            return items.map(item => {
                const { lat, lng } = extractCoords(item);
                const hasLocation = lat && lng;

                if (hasLocation && destIndex < elements.length) {
                    const element = elements[destIndex];
                    destIndex++;

                    if (element.status === 'OK' && element.distance) {
                        return {
                            ...item,
                            distance: Math.round((element.distance.value / 1000) * 10) / 10,
                            distanceIsExact: true,
                        };
                    } else {
                        return {
                            ...item,
                            // Preserve backend distance instead of recomputing
                            distance: item.distance ?? haversineDistance(oLat, oLng, lat, lng),
                            distanceIsExact: false,
                        };
                    }
                }

                return item;
            });
        }
    } catch (error) {
        console.error('Error fetching Distance Matrix:', error);
    }

    return applyHaversineFallback(items);
}


