import React from 'react';
import { Star } from 'lucide-react';
import { Badge } from '../ui/badge';

const ReviewBadge = ({ rating, count, className = '' }) => {
    // Don't render anything if there are no reviews
    if (!count || count === 0) return null;

    // Convert to number and round to 1 decimal place safely
    const numRating = Number(rating);
    const displayRating = isNaN(numRating) ? '0.0' : numRating.toFixed(1);

    return (
        <Badge variant="secondary" className={`flex items-center gap-2 bg-white/90 backdrop-blur-sm text-slate-800 shadow-sm border border-slate-200/50 hover:bg-white ${className}`}>
            <Star className="w-3.5 h-3.5 fill-amber-400 text-amber-400" />
            <span className="font-semibold">{displayRating}</span>
            {count !== undefined && (
                <span className="text-slate-500 font-normal ml-0.5">({count})</span>
            )}
        </Badge>
    );
};

export default ReviewBadge;
